"use client";
/* Sprout, from the Piixpal shadcn registry. Options: https://piixpal.vercel.app/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Sprout(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("sprout"); }, []);
  return React.createElement("piix-pal", { "pal": "sprout", ...piixAttrs(props) });
}

export default Sprout;
